import React, { useState, useEffect } from 'react';
import ProductCard from './ProductCard';
import { fetchFiltered } from '../api';

export default function ProductList({ products: initialProducts, onAdd }) {
  const [category, setCategory] = useState('');
  const [sort, setSort] = useState('');
  const [products, setProducts] = useState(initialProducts);

  useEffect(()=> setProducts(initialProducts), [initialProducts]);

  useEffect(() => {
    // fetch filtered list from server when category or sort changes
    fetchFiltered(category, sort).then(setProducts).catch(err => {
      console.error('fetchFiltered', err);
      setProducts(initialProducts);
    });
  }, [category, sort, initialProducts]);

  const categories = Array.from(new Set(initialProducts.map(p => p.category).filter(Boolean)));

  return (
    <div>
      <h2>Products</h2>

      <div className="controls">
        <select value={category} onChange={e=>setCategory(e.target.value)}>
          <option value="">All categories</option>
          {categories.map(c => <option key={c} value={c}>{c}</option>)}
        </select>

        <select value={sort} onChange={e=>setSort(e.target.value)}>
          <option value="">Sort</option>
          <option value="low-high">Price: Low → High</option>
          <option value="high-low">Price: High → Low</option>
        </select>
      </div>

      <div className="grid">
        {products.map(p => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
    </div>
  );
}
